{
  "chapters": [
    {
      "chapter": 3,
      "observed_unit_count": 1,
      "boundary_evidence": "The body begins immediately after the Roman heading III., partway through a printed line. It continues across the following two lines and ends at the four-dot punctuation after ከረምት. The next body line begins with IV. No separate numbered subdivision occurs between III. and IV.; the single unit is implicit at the heading.",
      "units": [
        {
          "verse": 1,
          "source_text": "*ጠይቁ፡ ወርእዩ፡ *ኵሎ፡ ዕፀወ፡ እፀ፡ ይስተርእዩ፡ ከመ፡ ይቤስ፡ ወኀለቁ፡ አ⟦?⟧ጽልሆሙ፡ ⟦?⟧፡ ዘእንበለ፡ *⟦?⟧ወ⟦?⟧ዕፀወ፡ ዘኢይትነፈ፡ እለ፡ ይጸንሑ፡ እምኀለ⟦?⟧፡ እስከ፡ ይመጽእ፡ ጽደ⟦?⟧፡ እም*ኀልእ፡ ወእም፡ ⟦?⟧ከረምት።",
          "critical_observations": [
            "The unit number 1 is implicit; it is not printed beside III.",
            "Superscript apparatus-reference numbers 23–32 are omitted from the transcription.",
            "The four body asterisks are retained, including the asterisk within እም*ኀልእ.",
            "No word separator has been inserted between the numeral-bearing expression and ዕፀወ, or between the final body numeral and ከረምት.",
            "The apparatus below the horizontal rule is excluded from the body. No apparatus suggestion has been substituted into the transcription."
          ],
          "uncertainties": [
            {
              "location": "Second body line of III., second glyph of አ⟦?⟧ጽልሆሙ",
              "proposed_reading": null,
              "actual_pixel_observation": "The glyph has a compact upper attachment and a rightward rounded component; its precise Ethiopic form is not settled from the supplied pixels.",
              "unresolved": true
            },
            {
              "location": "Second body line of III., short word immediately after አ⟦?⟧ጽልሆሙ፡",
              "proposed_reading": null,
              "actual_pixel_observation": "A short Ethiopic letter group is visible before the separator, but the forms cannot be distinguished confidently. The separator is clear.",
              "unresolved": true
            },
            {
              "location": "Second body line of III., first numeral-shaped glyph immediately after the asterisk preceding ዕፀወ",
              "proposed_reading": null,
              "actual_pixel_observation": "A baseline glyph with horizontal strokes above and below its central shape precedes a readable ወ. It is distinct from the raised apparatus number.",
              "unresolved": true
            },
            {
              "location": "Second body line of III., numeral-shaped glyph between ወ and ዕፀወ",
              "proposed_reading": null,
              "actual_pixel_observation": "A rounded baseline form with small upper and lower marks follows ወ. The superscript reference 27 lies separately above this region.",
              "unresolved": true
            },
            {
              "location": "Third body line of III., final glyph of እምኀለ⟦?⟧",
              "proposed_reading": null,
              "actual_pixel_observation": "The final glyph has a rounded rightward component and an upper stroke; its exact form remains unclear. The following separator is visible.",
              "unresolved": true
            },
            {
              "location": "Third body line of III., final glyph of ጽደ⟦?⟧",
              "proposed_reading": null,
              "actual_pixel_observation": "A narrow final glyph follows the readable ጽደ, with a descending stroke and a small lower component that do not permit a secure identification.",
              "unresolved": true
            },
            {
              "location": "Third body line of III., baseline numeral-shaped glyph immediately before ከረምት",
              "proposed_reading": null,
              "actual_pixel_observation": "A baseline sign with upper and lower horizontal marks precedes ከረምት without a visible word separator. The raised reference 31 is separate and has been removed.",
              "unresolved": true
            }
          ]
        }
      ]
    }
  ],
  "images_examined": [
    "pdf44-full",
    "pdf44-body-detail"
  ],
  "incomplete_regions": [],
  "limitations": [
    "This is a single-pass visual reading of the supplied page images, not examination of a separately retrieved PDF or manuscript.",
    "Unsettled printed forms are represented by literal ⟦?⟧ rather than reconstructed from meaning or apparatus readings."
  ]
}
